import React, { useState } from "react";
import Sidebar from "./components/Sidebar";
import Dashboard from "./pages/Dashboard";
import Transactions from "./pages/Transactions";
import Analytics from "./pages/Analytics";
import MobilePreview from "./pages/MobilePreview";
import { PageId } from "./types";
import { USER_PROFILE } from "./data/mockData";
import {
  LayoutDashboard,
  List,
  BarChart3,
  Smartphone,
} from "lucide-react";

const PAGES: Record<PageId, React.ReactNode> = {
  dashboard: <Dashboard />,
  transactions: <Transactions />,
  analytics: <Analytics />,
  mobile: <MobilePreview />,
};

const MOBILE_NAV: { id: PageId; label: string; icon: React.ReactNode }[] = [
  { id: "dashboard", label: "Home", icon: <LayoutDashboard size={20} /> },
  { id: "transactions", label: "Ledger", icon: <List size={20} /> },
  { id: "analytics", label: "Analytics", icon: <BarChart3 size={20} /> },
  { id: "mobile", label: "Mobile", icon: <Smartphone size={20} /> },
];

const App: React.FC = () => {
  const [page, setPage] = useState<PageId>("dashboard");

  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* Desktop sidebar */}
      <Sidebar currentPage={page} onNavigate={setPage} user={USER_PROFILE} />

      {/* Main content */}
      <main className="flex-1 min-w-0 pb-20 md:pb-0">{PAGES[page]}</main>

      {/* Mobile bottom nav */}
      <nav className="md:hidden fixed bottom-0 inset-x-0 bg-white border-t border-gray-100 flex z-50">
        {MOBILE_NAV.map((item) => (
          <button
            key={item.id}
            onClick={() => setPage(item.id)}
            className={`flex-1 flex flex-col items-center gap-1 py-2.5 text-[10px] font-medium transition-colors ${
              page === item.id ? "text-emerald-600" : "text-gray-400"
            }`}
          >
            <span className={page === item.id ? "text-emerald-600" : "text-gray-400"}>
              {item.icon}
            </span>
            {item.label}
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;
